CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(32) UNIQUE NOT NULL, email VARCHAR(190) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('member','moderator','admin') DEFAULT 'member', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE topics (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, title VARCHAR(120) NOT NULL, body TEXT NOT NULL, video_url VARCHAR(500), locked TINYINT DEFAULT 0, pinned TINYINT DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id));
CREATE TABLE topic_tags (topic_id INT NOT NULL, tag VARCHAR(40) NOT NULL);
CREATE TABLE replies (id INT AUTO_INCREMENT PRIMARY KEY, topic_id INT NOT NULL, user_id INT NOT NULL, body TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE reactions (id INT AUTO_INCREMENT PRIMARY KEY, reply_id INT NOT NULL, user_id INT NOT NULL, emoji VARCHAR(16) NOT NULL, UNIQUE KEY unique_reaction(reply_id,user_id,emoji));
CREATE TABLE uploads (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, topic_id INT, reply_id INT, file_path VARCHAR(255) NOT NULL, mime_type VARCHAR(100), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE purchases (id INT AUTO_INCREMENT PRIMARY KEY, provider_order_id VARCHAR(120) UNIQUE, username VARCHAR(32), product VARCHAR(190), amount DECIMAL(10,2), currency CHAR(3) DEFAULT 'USD', status VARCHAR(30), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE page_views (id BIGINT AUTO_INCREMENT PRIMARY KEY, path VARCHAR(255), visitor_hash CHAR(64), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
